class HERMES_EXPORT ProfileSampleCallStackJSFunctionFrame {
 public:
  explicit ProfileSampleCallStackJSFunctionFrame(
      std::string_view functionName,
      uint32_t scriptId,
      const std::optional<std::string_view> &scriptUrl = std::nullopt,
      const std::optional<uint32_t> &lineNumber = std::nullopt,
      const std::optional<uint32_t> &columnNumber = std::nullopt)
      : functionName_(functionName),
        scriptId_(scriptId),
        scriptUrl_(scriptUrl),
        lineNumber_(lineNumber),
        columnNumber_(columnNumber) {}

  std::string_view getFunctionName() const { return functionName_; }
  uint32_t getScriptId() const { return scriptId_; }
  bool hasScriptUrl() const { return scriptUrl_.has_value(); }
  std::string_view getScriptUrl() const { return scriptUrl_.value(); }
  bool hasFunctionLineNumber() const { return lineNumber_.has_value(); }
  uint32_t getFunctionLineNumber() const { return lineNumber_.value(); }
  bool hasFunctionColumnNumber() const { return columnNumber_.has_value(); }
  uint32_t getFunctionColumnNumber() const { return columnNumber_.value(); }

 private:
  std::string_view functionName_;
  uint32_t scriptId_;
  std::optional<std::string_view> scriptUrl_;
  std::optional<uint32_t> lineNumber_;
  std::optional<uint32_t> columnNumber_;
};

