import os
import random
import string
from typing import List

# Data type: filesystem path
# Target stub uses FUZZ_PARAM_FILENAME to provide a writable path for GCTripwireContext::createSnapshotToFile.
# Our goal: generate a bytes buffer that the fuzzer will place into a temporary file and pass its filename.
# Many fuzzers interpret FUZZ_PARAM_FILENAME() as: create temp file containing our bytes and return its path.
# Therefore, we should produce interesting, valid file contents that could exercise snapshot writing behavior
# (e.g., influencing permissions, existing/non-empty file, various sizes), and also occasionally include
# path-like hints in content names if the framework derives names. However, we cannot control the path string
# directly; we control file contents. Still, providing varied, realistic contents is useful. Keep <=4096 bytes.

# We will generate one of several content profiles:
# - Empty file
# - Small JSON-like content
# - Random ASCII text
# - Binary-like content with nulls
# - Repeated patterns
# - Large near-limit size
# - UTF-8 with multi-byte and some unusual code points
# - Lines with long lengths (no newlines)
# Selection is deterministic given seed.

MAX_SIZE = 4096

def _rand(r: random.Random, n: int) -> bytes:
    return bytes(r.getrandbits(8) for _ in range(n))

def _ascii_text(r: random.Random, n: int) -> bytes:
    alphabet = string.ascii_letters + string.digits + string.punctuation + ' \t\n'
    return ''.join(r.choice(alphabet) for _ in range(n)).encode('utf-8', 'strict')

def _json_like(r: random.Random) -> bytes:
    # Produce a simple JSON object with random keys/values to resemble metadata.
    kvs = []
    count = r.randint(2, 12)
    for i in range(count):
        klen = r.randint(3, 12)
        vlen = r.randint(0, 40)
        key = ''.join(r.choice(string.ascii_lowercase + string.digits + '_') for _ in range(klen))
        val_chars = string.ascii_letters + string.digits + ' .,:;_-'
        val = ''.join(r.choice(val_chars) for _ in range(vlen))
        kvs.append(f"\"{key}\": \"{val}\"")
    body = '{' + ', '.join(kvs) + '}'
    # Optionally add newline at end
    if r.random() < 0.5:
        body += '\n'
    return body.encode('utf-8')

def _utf8_text(r: random.Random, n: int) -> bytes:
    # Mix of ASCII and some multi-byte sequences
    out: List[str] = []
    while len(''.join(out).encode('utf-8')) < n:
        p = r.random()
        if p < 0.6:
            out.append(r.choice(string.ascii_letters + string.digits + ' '))
        elif p < 0.8:
            # Common punctuation
            out.append(r.choice('-_.,:;!@#()[]{}'))
        else:
            # Add some non-ASCII characters
            cp_pool = [0x00A9, 0x03B1, 0x03C0, 0x20AC, 0x221E, 0x2603, 0x1F600, 0x1F680]
            out.append(chr(r.choice(cp_pool)))
    data = ''.join(out).encode('utf-8')
    return data[:n]

def _binary_with_nuls(r: random.Random, n: int) -> bytes:
    # Include a null every so often and random bytes otherwise
    data = bytearray()
    for i in range(n):
        if i % r.randint(8, 32) == 0:
            data.append(0)
        else:
            data.append(r.getrandbits(8))
    return bytes(data)

def _repeated_pattern(r: random.Random, n: int) -> bytes:
    patterns = [b'\x00', b'\xff', b'AB', b'\n', b'\r\n', b'0123456789', b'====', b'\xDE\xAD\xBE\xEF']
    pat = r.choice(patterns)
    return (pat * (n // len(pat) + 1))[:n]

def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Choose profile
    profiles = ['empty', 'json', 'ascii', 'binary', 'pattern', 'large', 'utf8', 'longline']
    choice = r.choice(profiles)

    if choice == 'empty':
        return b''

    if choice == 'json':
        return _json_like(r)

    if choice == 'ascii':
        size = r.randint(1, 512)
        return _ascii_text(r, size)

    if choice == 'binary':
        size = r.randint(1, 1024)
        return _binary_with_nuls(r, size)

    if choice == 'pattern':
        size = r.randint(1, 2048)
        return _repeated_pattern(r, size)

    if choice == 'utf8':
        size = r.randint(10, 1000)
        return _utf8_text(r, size)

    if choice == 'longline':
        # Very long single line without newline to test streaming behaviors
        size = r.randint(100, 2000)
        return _ascii_text(r, size).replace(b"\n", b" ")

    if choice == 'large':
        # Near maximum allowed size with structured header/footer
        header = b"HERMES_SNAPSHOT_TEST\n"
        footer = b"\nEND\n"
        remaining = MAX_SIZE - len(header) - len(footer)
        middle_choice = r.choice(['binary', 'pattern', 'utf8'])
        if middle_choice == 'binary':
            middle = _binary_with_nuls(r, remaining)
        elif middle_choice == 'pattern':
            middle = _repeated_pattern(r, remaining)
        else:
            middle = _utf8_text(r, remaining)
        return header + middle + footer

    # Fallback
    return b'test'
